-- ================================================-- 017 - 修复查看员角色权限-- 删除 viewer 角色不该有的菜单权限（食材管理）-- ================================================-- 删除 viewer 角色的食材管理权限DELETE FROM role_permissions WHERE role_id = (SELECT id FROM roles WHERE code = 'viewer')  AND permission_id IN (SELECT id FROM permissions WHERE code = 'menu:ingredient-manager');-- 验证结果SELECT  r.code AS role_code,  r.name AS role_name,  p.code AS perm_code,  p.name AS perm_name,  p.pathFROM roles rJOIN role_permissions rp ON r.id = rp.role_idJOIN permissions p ON rp.permission_id = p.idWHERE r.code = 'viewer'  AND p.type = 'menu'ORDER BY p.sort_order;SELECT '017_fix_viewer_permissions.sql 执行完成' AS message;